import type {FC} from 'react';
import React from 'react';

import {type IconData, getConfig} from '@gravity-ui/uikit';

import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import type {IconRefugeProps} from '../IconRefuge';
import {IconRefuge} from '../IconRefuge';

import {cnIssueTypeIcon} from './IssueTypeIcon.classname';
import {defaultMessages} from './i18n';
import type {IssueType} from './types';

import bugIcon from '../../../../assets/icons/issue-type/bug.svg';
import designIcon from '../../../../assets/icons/issue-type/design.svg';
import epicIcon from '../../../../assets/icons/issue-type/epic.svg';
import improvementIcon from '../../../../assets/icons/issue-type/improvement.svg';
import incidentIcon from '../../../../assets/icons/issue-type/incident.svg';
import infoIcon from '../../../../assets/icons/issue-type/info.svg';
import milestoneIcon from '../../../../assets/icons/issue-type/milestone.svg';
import newFeatureIcon from '../../../../assets/icons/issue-type/new-feature.svg';
import queryIcon from '../../../../assets/icons/issue-type/query.svg';
import refactoringIcon from '../../../../assets/icons/issue-type/refactoring.svg';
import releaseIcon from '../../../../assets/icons/issue-type/release.svg';
import researchIcon from '../../../../assets/icons/issue-type/research.svg';
import serviceRequestIcon from '../../../../assets/icons/issue-type/service-request.svg';
import storyIcon from '../../../../assets/icons/issue-type/story.svg';
import subbugIcon from '../../../../assets/icons/issue-type/subbug.svg';
import subtaskIcon from '../../../../assets/icons/issue-type/subtask.svg';
import taskIcon from '../../../../assets/icons/issue-type/task.svg';
import technicalDebtIcon from '../../../../assets/icons/issue-type/technical-debt.svg';

import './IssueTypeIcon.scss';

export type IssueTypeIconProps = Partial<Pick<IconRefugeProps, 'containerClassName' | 'title'>> & {
    className?: string;
    size?: number;
    issueType?: IssueType;
};

const ISSUE_TYPE_ICONS: Record<IssueType, IconData> = {
    bug: bugIcon,
    design: designIcon,
    epic: epicIcon,
    improvement: improvementIcon,
    incident: incidentIcon,
    info: infoIcon,
    milestone: milestoneIcon,
    newFeature: newFeatureIcon,
    query: queryIcon,
    refactoring: refactoringIcon,
    release: releaseIcon,
    research: researchIcon,
    serviceRequest: serviceRequestIcon,
    story: storyIcon,
    subBug: subbugIcon,
    subTask: subtaskIcon,
    task: taskIcon,
    technicalDebt: technicalDebtIcon,
};

export const IssueTypeIcon: FC<IssueTypeIconProps> = ({
    className,
    containerClassName,
    issueType = 'task',
    size = 16,
    title,
}) => {
    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);
    const ariaLabel = title ? t('type-label', {type: issueType}) : undefined;

    return (
        <IconRefuge
            className={cnIssueTypeIcon({type: issueType}, className)}
            containerClassName={containerClassName}
            data={ISSUE_TYPE_ICONS[issueType] ?? taskIcon}
            refugeSize={size}
            title={title}
            aria-label={ariaLabel}
            aria-hidden={!title || undefined}
        />
    );
};

IssueTypeIcon.displayName = 'IssueTypeIcon';
